mapper.update:
update inv_sales_return_detail
set returned_quantity = #{returnedQuantity}, returned_cost_amount = #{returnedCostAmount},
    sales_detail_id = #{salesDetailId}, item_type = #{itemType}, item_id = #{itemId}
where detail_id = #{detailId}

mapper.select:
select coalesce(sum(d.quantity), 0)
from inv_sales_return_detail d
inner join inv_sales_return r on r.return_id = d.return_id
where r.sales_order_id = #{salesOrderId}
  and d.product_id = #{productId}
  and r.status in ('submitted', 'returned')

  and r.return_id != #{excludeReturnId}

select coalesce(sum(d.quantity), 0)
from inv_sales_return_detail d
inner join inv_sales_return r on r.return_id = d.return_id
where r.sales_order_id = #{salesOrderId}
  and coalesce(nullif(d.item_type, ''), 'product') = #{itemType}
  and coalesce(d.item_id, d.product_id) = #{itemId}
  and r.status in ('submitted', 'returned')

  and r.return_id != #{excludeReturnId}

for update

select coalesce(sum(d.quantity), 0) from inv_sales_return_detail d inner join inv_sales_return r on r.return_id = d.return_id where r.sales_order_id = #{salesOrderId} and (d.sales_detail_id = #{salesDetailId} or (d.sales_detail_id is null and exists ( select 1 from inv_sales_detail sd where sd.detail_id = #{salesDetailId} and sd.order_id = r.sales_order_id and coalesce(nullif(sd.item_type, ''), 'product') = coalesce(nullif(d.item_type, ''), 'product') and coalesce(sd.item_id, sd.product_id) = coalesce(d.item_id, d.product_id) ))) and r.status in ('submitted', 'returned')
and r.return_id != #{excludeReturnId}
for update
